mapper.update:
UPDATE user_api_key
SET status = #{status,jdbcType=SMALLINT},
    expires_at = #{expiresAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    row_version = row_version + 1
WHERE id = #{id,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND row_version = #{expectedRowVersion,jdbcType=BIGINT}
  AND status IN (0, 1)
  AND (
      status IS DISTINCT FROM #{status,jdbcType=SMALLINT}
      OR expires_at IS DISTINCT FROM #{expiresAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
  )

UPDATE user_api_key
SET status = 2,
    deleted_at = #{deletedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    row_version = row_version + 1
WHERE id = #{id,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND row_version = #{expectedRowVersion,jdbcType=BIGINT}
  AND status IN (0, 1)

UPDATE user_api_key
SET last_used_at = #{lastUsedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{id,jdbcType=BINARY}
  AND status = 1

UPDATE user_api_key
SET row_version = row_version + 1
WHERE id = #{id,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND row_version = #{expectedRowVersion,jdbcType=BIGINT}
  AND status IN (0, 1)
